// A brief is not a condition that opens and recovers, so it carries no
// alert_key and no state. Branch on the event type before anything else: this
// workflow shares a destination with viryaos.ops.status_changed, not a shape.
const e = $json;
if (!e || e.type !== 'viryaos.ops.operator_brief' || e.version !== 1) return [];
const d = e.data ?? {};
if (!d.headline || !d.summary) throw new Error('Invalid operator brief');
const s = d.snapshot ?? {};

// CrowdRelay decided there was something worth saying and sends at most one a
// day. Never suppress, batch or re-send: a delivery path that applies its own
// quiet hours reproduces the silence the brief exists to break.
const HEADLINES = {
  approval_stale: {icon: '\u23F0', label: 'A decision has been waiting too long'},
  disabled_with_work_waiting: {icon: '\u26A0\uFE0F', label: 'The agent is not running while work waits'},
  work_parked: {icon: '\u{1F6A7}', label: 'Work is parked with no executor for it'},
  awaiting_approval: {icon: '\u{1F464}', label: 'Decisions need you'},
  failing: {icon: '\u274C', label: 'Actions failed'},
  blind: {icon: '\u{1F441}\uFE0F', label: 'The agent cannot see some platforms'},
  worked: {icon: '\u2705', label: 'The agent worked'}
};
const h = HEADLINES[d.headline] ?? {icon: '\u2139\uFE0F', label: d.headline};

// Facts only. The brief reports; the read models and the operator decide.
const lines = [
  `${h.icon} *VIRYA \u2014 ${h.label}*`,
  '',
  d.summary,
  '',
  `Executed (24h): ${s.actions_executed_24h ?? 0}`,
  `Failed (24h): ${s.actions_failed_24h ?? 0}`,
  `Awaiting approval: ${s.actions_awaiting_approval ?? 0}`,
  `Parked (no executor): ${s.actions_parked ?? 0}`,
  `Platforms not visible: ${s.blind_platforms ?? 0}`,
  `Agent: ${s.agent_enabled ? 'enabled' : 'disabled'}${s.dry_run ? ', dry run' : ''}`,
  '',
  $env.VIRYA_STAFF_TODAY_URL ? `Queue: ${$env.VIRYA_STAFF_TODAY_URL}` : ''
].filter(Boolean);

return [{ json: {
  event_id: e.id,
  headline: d.headline,
  observed_at: d.observed_at,
  subject: `VIRYA daily brief \u2014 ${h.label}`,
  text: lines.join('\n')
}}];
